        "solutionCode": "public class Solution {\n    static class BookRating {\n        private String title;\n        private int totalStars = 0;\n        private int reviewCount = 0;\n\n        public BookRating(String title) {\n            this.title = title;\n        }\n\n        public boolean addRating(int stars) {\n            if (stars < 1 || stars > 5) {\n                return false;\n            }\n            totalStars += stars;\n            reviewCount++;\n            return true;\n        }\n\n        public double getAverageRating() {\n            if (reviewCount == 0) return 0.0;\n            return (double) totalStars / reviewCount;\n        }\n\n        public String getTitle() { return title; }\n        public int getReviewCount() { return reviewCount; }\n    }\n\n    public static void main(String[] args) {\n        BookRating book = new BookRating(\"Effective Java\");\n        System.out.println(\"Add 6 Stars: \" + book.addRating(6));\n        System.out.println(\"Add 5 Stars: \" + book.addRating(5));\n        System.out.println(\"Add 4 Stars: \" + book.addRating(4));\n        System.out.println(\"Add 5 Stars: \" + book.addRating(5));\n        System.out.println(\"Total Reviews: \" + book.getReviewCount());\n        System.out.printf(\"Average Rating: %.2f%n\", book.getAverageRating());\n    }\n}",
