        "solutionCode": "public class Solution {\n    static class BoardingPass {\n        private final String ticketNumber;\n        private String passengerName;\n        private String seatNumber;\n\n        public BoardingPass(String ticketNumber, String passengerName, String seatNumber) {\n            if (passengerName == null || passengerName.trim().isEmpty()) {\n                throw new IllegalArgumentException(\"Passenger name cannot be blank\");\n            }\n            this.ticketNumber = ticketNumber;\n            this.passengerName = passengerName;\n            this.seatNumber = seatNumber;\n        }\n\n        public String getTicketNumber() { return ticketNumber; }\n        public String getPassengerName() { return passengerName; }\n        public String getSeatNumber() { return seatNumber; }\n\n        public boolean setSeatNumber(String newSeat) {\n            if (newSeat != null && !newSeat.trim().isEmpty()) {\n                this.seatNumber = newSeat;\n                return true;\n            }\n            return false;\n        }\n    }\n\n    public static void main(String[] args) {\n        BoardingPass pass = new BoardingPass(\"TK-88910\", \"Elena Rostova\", \"14B\");\n        System.out.println(\"Ticket: \" + pass.getTicketNumber() + \" | Passenger: \" + pass.getPassengerName());\n        System.out.println(\"Original Seat: \" + pass.getSeatNumber());\n\n        pass.setSeatNumber(\"2A\");\n        System.out.println(\"Updated Seat: \" + pass.getSeatNumber());\n        System.out.println(\"Ticket number remains immutable: \" + pass.getTicketNumber());\n    }\n}",
