        "hint": "Return a cloned array or new ArrayList in getItems() to prevent external callers from modifying cart state.",
        "solutionCode": "import java.util.ArrayList;\nimport java.util.List;\n\npublic class Solution {\n    static class Item {\n        private final String name;\n        private final double price;\n        private final int quantity;\n\n        public Item(String name, double price, int quantity) {\n            this.name = name;\n            this.price = price;\n            this.quantity = quantity;\n        }\n\n        public String getName() { return name; }\n        public double getPrice() { return price; }\n        public int getQuantity() { return quantity; }\n    }\n\n    static class ShoppingCart {\n        private final List<Item> items = new ArrayList<>();\n\n        public boolean addItem(String name, double price, int quantity) {\n            if (price <= 0.0 || quantity <= 0) return false;\n            items.add(new Item(name, price, quantity));\n            return true;\n        }\n\n        public List<Item> getItems() {\n            return new ArrayList<>(items);\n        }\n\n        public double calculateTotal() {\n            double total = 0.0;\n            for (Item item : items) {\n                total += item.getPrice() * item.getQuantity();\n            }\n            return total;\n        }\n    }\n\n    public static void main(String[] args) {\n        ShoppingCart cart = new ShoppingCart();\n        cart.addItem(\"Keyboard\", 50.0, 2);\n        cart.addItem(\"Mouse\", 25.0, 1);\n\n        List<Item> leaked = cart.getItems();\n        leaked.clear();\n\n        System.out.printf(\"Cart Total: $%.2f%n\", cart.calculateTotal());\n        System.out.println(\"Cart Items Retained: \" + cart.getItems().size());\n    }\n}",
